+ '<div class="ccomp-col"><div class="ccomp-title" style="color:#4ecdc4;">BART</div><div class="ccomp-body">'
+ '<table style="width:100%;border-collapse:collapse;font-size:0.85rem;">'
+ '<tr><td style="padding:5px 6px;border-bottom:1px solid #333;color:#aaa;">Architecture</td><td style="padding:5px 6px;border-bottom:1px solid #333;color:#e0e0e0;">Encoder-decoder transformer, RoBERTa-style encoder</td></tr>'
+ '<tr><td style="padding:5px 6px;border-bottom:1px solid #333;color:#aaa;">Pre-training</td><td style="padding:5px 6px;border-bottom:1px solid #333;color:#e0e0e0;">Denoising autoencoder with 5 noise types on Books + Wikipedia</td></tr>'
+ '<tr><td style="padding:5px 6px;border-bottom:1px solid #333;color:#aaa;">Task format</td><td style="padding:5px 6px;border-bottom:1px solid #333;color:#e0e0e0;">Raw text in, raw text out. No task prefix needed.</td></tr>'
