+ '<tr><td style="padding:5px 6px;border-bottom:1px solid #333;color:#aaa;">Best for</td><td style="padding:5px 6px;border-bottom:1px solid #333;color:#e0e0e0;">Summarization, dialogue, question generation, abstractive tasks</td></tr>'
+ '<tr><td style="padding:5px 6px;color:#aaa;">ROUGE (CNN/DM)</td><td style="padding:5px 6px;color:#e0e0e0;">R-1: 44.2, R-2: 21.3, R-L: 40.9 (bart-large-cnn)</td></tr>'
