+ '<tr><td style="padding:5px 6px;color:#aaa;">ROUGE (CNN/DM)</td><td style="padding:5px 6px;color:#e0e0e0;">R-1: 44.2, R-2: 21.5, R-L: 41.1 (pegasus-large)</td></tr>'
